tool.command:
mkdir -p run && cd run &&
printf '%s\n' 'sim3de' '$output' '$nels $nxe $nze' '$aa $bb $cc' '$thx $thy $thz' '$emn $esd' '$varfnc' '0.3' > rfem.rf &&
rfemcube rfem model 2>&1;
RC=\$?;
if [ -f model.d ];   then cp model.d   '$output_d';   else echo "rfemcube: no .d output (exit \${RC})" > '$output_d'; fi;
if [ -f model.dat ]; then cp model.dat '$output_dat'; else echo "rfemcube: no .dat output" > '$output_dat'; fi;
if [ -f rfem.res ];  then cp rfem.res  '$output_res'; else echo "rfemcube: no .res output" > '$output_res'; fi;
exit \${RC}
